// GENERATED by npm run sync from the website's src/cms/code.ts. Change it there.
/**
 * 内置模板代码 (the owner, 2026-11-16: a built-in template checked out, downloaded and uploaded in the CMS, through its
 * workflow, onto a cms-preview branch, then pushed): the rules a built-in template's file (views/<type>.tsx) keeps, so
 * one replaced through the CMS only draws. It imports the site's components and words and nothing that reaches further;
 * it names no network, storage, cookie, code-from-text or Node; it writes no HTML as text and draws no script, style or
 * frame, except where its type's own view needs one (RAW). The CMS checks an upload with `checkViewCode` before it takes
 * it (npm run sync brings it this file); this repository's tests hold every file of views/ to it.
 *
 * Not a sandbox: a template is code that runs in every visitor's browser and in the build, so the CMS lets only 超级管理员
 * replace one, the workflow shows it on preview first, and the build checks its types before it goes anywhere.
 */
import ts from "typescript";

/** A problem with a template's code: its code (the CMS says it as code.<code>) and what it names. */
export type CodeProblem = { code: string; values: Record<string, string | number> };

const problem = (code: string, values: CodeProblem["values"] = {}): CodeProblem => ({ code, values });

/** Where the built-in templates are in this repository, one file each. */
export const CODE_DIR = "src/cms/views";
export const codePath = (type: string) => `${CODE_DIR}/${type}.tsx`;
export const CODE_LIMIT = 100_000;

/** What a template may import: the site's components, icons and words. */
export const IMPORTS = [
  "react",
  "@mantine/core",
  "@mantine/hooks",
  "@tabler/icons-react",
  "next-intl",
  "@/components/bits",
  "@/components/service-cards",
  "@/config/apps",
  "@/i18n/routing",
  "@/lib/session",
  "../site",
  "./parts",
];

/** Names a template never uses: the network, storage, other windows, code from text, Node. */
const GLOBALS = new Set([
  "fetch",
  "XMLHttpRequest",
  "WebSocket",
  "EventSource",
  "eval",
  "Function",
  "localStorage",
  "sessionStorage",
  "indexedDB",
  "caches",
  "navigator",
  "window",
  "document",
  "self",
  "top",
  "parent",
  "opener",
  "frames",
  "globalThis",
  "importScripts",
  "Worker",
  "SharedWorker",
  "process",
  "require",
  "module",
  "exports",
]);

/** Properties never read or written: cookies, HTML as text, beacons. */
const PROPERTIES = new Set([
  "cookie",
  "innerHTML",
  "outerHTML",
  "insertAdjacentHTML",
  "createContextualFragment",
  "createElement",
  "sendBeacon",
  "write",
  "writeln",
]);

/** Elements never drawn, and the attributes that put HTML in as text. */
const ELEMENTS = new Set(["script", "style", "link", "meta", "base", "object", "embed", "iframe", "frame"]);
const ATTRIBUTES = new Set(["dangerouslySetInnerHTML", "srcDoc"]);

/**
 * What a type's own view needs of the above: 图文 shows the HTML the CMS sanitised, 自由 HTML its HTML in the page itself
 * and its scripts run (the owner, 2026-11-17).
 */
export const RAW: Record<string, string[]> = {
  rich_text: ["dangerouslySetInnerHTML"],
  freeform: ["dangerouslySetInnerHTML", "document", "createElement"],
};

/** A name used as a value here, not a property's, a key's or an attribute's name. */
function isReference(node: ts.Identifier) {
  const p = node.parent;
  if (ts.isPropertyAccessExpression(p) && p.name === node) return false;
  if (
    (ts.isPropertyAssignment(p) || ts.isPropertySignature(p) || ts.isMethodDeclaration(p)) &&
    p.name === node
  )
    return false;
  if (ts.isJsxAttribute(p) || ts.isQualifiedName(p)) return false;
  return true;
}

/** Every problem with [source] as the built-in template of [type]; none: it may be taken. */
export function checkViewCode(source: string, type: string): CodeProblem[] {
  if (!source.trim()) return [problem("empty")];
  if (source.length > CODE_LIMIT) return [problem("tooLong", { max: CODE_LIMIT })];
  const syntax = ts.transpileModule(source, {
    fileName: `${type}.tsx`,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.Preserve,
      target: ts.ScriptTarget.ESNext,
      module: ts.ModuleKind.ESNext,
    },
  }).diagnostics;
  const file = ts.createSourceFile(`${type}.tsx`, source, ts.ScriptTarget.ESNext, true, ts.ScriptKind.TSX);
  const lineOf = (pos: number) => file.getLineAndCharacterOfPosition(pos).line + 1;
  if (syntax?.length)
    return syntax.slice(0, 5).map((d) =>
      problem("syntax", {
        line: d.start === undefined ? 0 : lineOf(d.start),
        text: ts.flattenDiagnosticMessageText(d.messageText, " "),
      }),
    );
  const out: CodeProblem[] = [];
  const allowed = new Set(RAW[type] ?? []);
  const first = file.statements[0];
  if (
    !first ||
    !ts.isExpressionStatement(first) ||
    !ts.isStringLiteral(first.expression) ||
    first.expression.text !== "use client"
  )
    out.push(problem("useClient"));
  const exportsDefault = file.statements.some(
    (s) =>
      (ts.isExportAssignment(s) && !s.isExportEquals) ||
      (ts.isFunctionDeclaration(s) &&
        s.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword) &&
        s.modifiers.some((m) => m.kind === ts.SyntaxKind.DefaultKeyword)),
  );
  if (!exportsDefault) out.push(problem("noDefault"));
  const visit = (node: ts.Node) => {
    const line = () => lineOf(node.getStart(file));
    if ((ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) && node.moduleSpecifier) {
      const from = (node.moduleSpecifier as ts.StringLiteral).text;
      if (!IMPORTS.includes(from)) out.push(problem("import", { module: from, line: line() }));
    } else if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword)
      out.push(problem("dynamicImport", { line: line() }));
    else if (ts.isIdentifier(node) && GLOBALS.has(node.text) && !allowed.has(node.text) && isReference(node))
      out.push(problem("global", { name: node.text, line: line() }));
    else if (
      ts.isPropertyAccessExpression(node) &&
      PROPERTIES.has(node.name.text) &&
      !allowed.has(node.name.text)
    )
      out.push(problem("property", { name: node.name.text, line: line() }));
    else if (
      ts.isElementAccessExpression(node) &&
      ts.isStringLiteralLike(node.argumentExpression) &&
      (PROPERTIES.has(node.argumentExpression.text) || GLOBALS.has(node.argumentExpression.text))
    )
      out.push(problem("property", { name: node.argumentExpression.text, line: line() }));
    else if (
      (ts.isIdentifier(node) || ts.isStringLiteralLike(node)) &&
      ATTRIBUTES.has(node.text) &&
      !allowed.has(node.text)
    )
      out.push(problem("attribute", { name: node.text, line: line() }));
    else if (ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) {
      // An element of the page's own (lower case), not a component (Link is next-intl's).
      const tag = node.tagName.getText(file);
      if (ELEMENTS.has(tag) && !allowed.has(tag)) out.push(problem("element", { tag, line: line() }));
    } else if (
      ts.isJsxAttribute(node) &&
      node.name.getText(file) === "component" &&
      node.initializer &&
      ts.isStringLiteral(node.initializer) &&
      ELEMENTS.has(node.initializer.text) &&
      !allowed.has(node.initializer.text)
    )
      out.push(problem("element", { tag: node.initializer.text, line: line() }));
    ts.forEachChild(node, visit);
  };
  visit(file);
  return out;
}
